import{_ as r,o,c as t,a2 as a}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Kernel 日报 2026-11-14","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/14.md","filePath":"notes/kernel-digest/2026/11/14.md"}'),n={name:"notes/kernel-digest/2026/11/14.md"};function l(i,e,c,s,d,u){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="kernel-日报-2026-11-14" tabindex="-1">Kernel 日报 2026-11-14 <a class="header-anchor" href="#kernel-日报-2026-11-14" aria-label="Permalink to &quot;Kernel 日报 2026-11-14&quot;">​</a></h1><blockquote><p>生成时间：2026-11-14T02:44:26Z｜共 32 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-14 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_5e4f7834d14d-·-announcing-xraid-declustered-parity-raid-for-zoned-xfs" tabindex="-1"><code>5e4f7834d14d</code> · <a href="https://lwn.net/Articles/1107473/" target="_blank" rel="noreferrer">Announcing XRAID: declustered parity RAID for zoned XFS</a> <a class="header-anchor" href="#_5e4f7834d14d-·-announcing-xraid-declustered-parity-raid-for-zoned-xfs" aria-label="Permalink to &quot;`5e4f7834d14d` · [Announcing XRAID: declustered parity RAID for zoned XFS](https://lwn.net/Articles/1107473/)&quot;">​</a></h3><p><em>jzb｜lwn｜文件系统与存储</em></p><p>Christoph Hellwig 发布了 XRAID 的首个公开版本，这是集成到 XFS 中的 declustered parity RAID 实现。其两大目标是支持 SMR 等分区设备（zoned devices）上的 parity RAID，以及提供没有固有数据一致性问题的快速 RAID 实现；在传统硬盘上写入速度最高比 mdraid 快 20 倍。该项目已开发一年半，距离合并到主线仍需时间。</p><blockquote><p><strong>学习价值</strong>：对学习文件系统与存储栈（XFS、zoned devices、RAID）的读者极具价值，展示了文件系统级 RAID 设计的前沿方向。</p></blockquote><h3 id="c8ee564f3909-·-patch-v8-0-3-rust-spi-add-spi-driver-abstractions" tabindex="-1"><code>c8ee564f3909</code> · <a href="https://lore.kernel.org/all/tencent_5FBF490F375F4C66A2C8DD421A8E8542FE05@qq.com/" target="_blank" rel="noreferrer">[PATCH v8 0/3] rust: spi: add SPI driver abstractions</a> <a class="header-anchor" href="#c8ee564f3909-·-patch-v8-0-3-rust-spi-add-spi-driver-abstractions" aria-label="Permalink to &quot;`c8ee564f3909` · [[PATCH v8 0/3] rust: spi: add SPI driver abstractions](https://lore.kernel.org/all/tencent_5FBF490F375F4C66A2C8DD421A8E8542FE05@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux｜Rust in Linux</em></p><p>本系列 cover letter 汇总了为 SPI 子系统添加 Rust 抽象的三部分补丁（helpers、抽象层、示例驱动）。v8 相对 v7 的主要变化是 rebase 到 linux-next、改为全新邮件线程发送，并根据 Mark Brown 的评审意见将设备 I/O 重构为映射到 spi_sync() 的 transfer() 原语。</p><blockquote><p><strong>学习价值</strong>：通过版本演进记录展示了内核社区评审驱动的迭代过程，可学习补丁系列的组织与回应评审的方式。</p></blockquote><h3 id="f915d898c779-·-patch-v3-4-4-mm-damon-core-use-node-counters-instead-of-flushing-the-root-memcg" tabindex="-1"><code>f915d898c779</code> · <a href="https://lore.kernel.org/all/20261114002822.1043378-5-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 4/4] mm/damon/core: use node counters instead of flushing the root memcg</a> <a class="header-anchor" href="#f915d898c779-·-patch-v3-4-4-mm-damon-core-use-node-counters-instead-of-flushing-the-root-memcg" aria-label="Permalink to &quot;`f915d898c779` · [[PATCH v3 4/4] mm/damon/core: use node counters instead of flushing the root memcg](https://lore.kernel.org/all/20261114002822.1043378-5-joannelkoong@gmail.com/)&quot;">​</a></h3><p><em>Joanne Koong (<a href="mailto:joannelkoong@gmail.com" target="_blank" rel="noreferrer">joannelkoong@gmail.com</a>)｜linux-mm｜内存管理</em></p><p>该补丁修改 damos_get_node_memcg_used_bp()，在评估 DAMON goal 时对 root memcg 跳过 memcg stats flush。此前对 root memcg 的 flush 会级联刷新系统中所有 cgroup 且没有限流，开销很大；现在 lruvec_page_state() 可直接从始终最新的 node counters 读取 root memcg 的 LRU 大小。</p><blockquote><p><strong>学习价值</strong>：揭示了 memcg rstat flush 的全局代价以及 node counters 优化路径，对理解 DAMON 与 memcg 统计机制很有价值。</p></blockquote><h3 id="_71efb1908617-·-linux-7-5-to-include-new-hwpoison-panic-tool-for-intentionally-crashing-your-system" tabindex="-1"><code>71efb1908617</code> · <a href="https://www.phoronix.com/news/Linux-7.5-hwpoison-panic" target="_blank" rel="noreferrer">Linux 7.5 To Include New hwpoison-panic Tool For Intentionally Crashing Your System</a> <a class="header-anchor" href="#_71efb1908617-·-linux-7-5-to-include-new-hwpoison-panic-tool-for-intentionally-crashing-your-system" aria-label="Permalink to &quot;`71efb1908617` · [Linux 7.5 To Include New hwpoison-panic Tool For Intentionally Crashing Your System](https://www.phoronix.com/news/Linux-7.5-hwpoison-panic)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>预计合并进 Linux 7.5 的新工具 hwpoison-panic 可通过 hwpoison 机制故意注入内存错误使系统崩溃，用于测试和演练内核的硬件错误处理路径。这是 RAS（可靠性、可用性、可服务性）测试基础设施的一部分。</p><blockquote><p><strong>学习价值</strong>：对学习内存管理中的 hwpoison 机制和 RAS 错误处理路径很有参考价值，展示了内核如何做故障注入测试。</p></blockquote><h3 id="e40de6443c70-·-patch-0-1-rust-pwm-reject-over-aligned-driver-data-in-chip-new" tabindex="-1"><code>e40de6443c70</code> · <a href="https://lore.kernel.org/all/cover.1794600927.git.pgovind2@uci.edu/" target="_blank" rel="noreferrer">[PATCH 0/1] rust: pwm: reject over-aligned driver data in <code>Chip::new()</code></a> <a class="header-anchor" href="#e40de6443c70-·-patch-0-1-rust-pwm-reject-over-aligned-driver-data-in-chip-new" aria-label="Permalink to &quot;`e40de6443c70` · [[PATCH 0/1] rust: pwm: reject over-aligned driver data in `Chip::new()`](https://lore.kernel.org/all/cover.1794600927.git.pgovind2@uci.edu/)&quot;">​</a></h3><p><em>Priya Bala Govindasamy (<a href="mailto:pgovind2@uci.edu" target="_blank" rel="noreferrer">pgovind2@uci.edu</a>)｜rust-for-linux｜Rust in Linux</em></p><p>该补丁系列由 FerroLens 工具（内部使用 LLM 检测 Rust 内核代码潜在 unsound 行为并经人工验证）发现的问题驱动。问题为 rust/kernel/pwm.rs 中 <code>Chip::new()</code> 未检查驱动数据类型 <code>T</code> 的对齐，可能导致 <code>pwmchip_alloc()</code> 分配的存储不满足 <code>T</code> 的对齐要求。</p><blockquote><p><strong>学习价值</strong>：展示了 LLM 辅助工具在内核 Rust 代码审计中的实际应用，是工具与内核开发结合的有趣范例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（4 条）</li><li><strong>网络</strong>（1 条）</li><li><strong>文件系统与存储</strong>（2 条）</li><li><strong>Rust in Linux</strong>（15 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（9 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="c08b72928c4d-·-amd-leverages-ai-hrx-loom-in-experiment-for-quickly-porting-50-llms-to-client-gpus" tabindex="-1"><code>c08b72928c4d</code> · <a href="https://www.phoronix.com/news/AMD-HRX-Loom-Experiment" target="_blank" rel="noreferrer">AMD Leverages AI + HRX Loom In Experiment For Quickly Porting 50 LLMs To Client GPUs</a> <a class="header-anchor" href="#c08b72928c4d-·-amd-leverages-ai-hrx-loom-in-experiment-for-quickly-porting-50-llms-to-client-gpus" aria-label="Permalink to &quot;`c08b72928c4d` · [AMD Leverages AI + HRX Loom In Experiment For Quickly Porting 50 LLMs To Client GPUs](https://www.phoronix.com/news/AMD-HRX-Loom-Experiment)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 团队借助刚发布的 HRX Loom v0.1 和 AI agent 工作流，在约三天内将 50 个 Hugging Face 热门大模型移植到 AMD 客户端 GPU 上，依托 Ryzen AI Max &quot;Strix Halo&quot; 硬件完成。</p><blockquote><p><strong>学习价值</strong>：属于 AI 软件栈与 GPU 生态新闻，与内核内存管理无关，原分类有误。</p></blockquote><h3 id="_37ce30cca127-·-akpm-mm-mm-new-build-success-31a696f9c37defab0f28f774e00ac7f135889ec3" tabindex="-1"><code>37ce30cca127</code> · <a href="https://lore.kernel.org/all/20261114101453.lXVCUJvX-lkp@intel.com/" target="_blank" rel="noreferrer">[akpm-mm:mm-new] BUILD SUCCESS 31a696f9c37defab0f28f774e00ac7f135889ec3</a> <a class="header-anchor" href="#_37ce30cca127-·-akpm-mm-mm-new-build-success-31a696f9c37defab0f28f774e00ac7f135889ec3" aria-label="Permalink to &quot;`37ce30cca127` · [[akpm-mm:mm-new] BUILD SUCCESS 31a696f9c37defab0f28f774e00ac7f135889ec3](https://lore.kernel.org/all/20261114101453.lXVCUJvX-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:lkp@intel.com" target="_blank" rel="noreferrer">lkp@intel.com</a>)｜linux-mm</em></p><p>kernel test robot 报告 akpm mm-new 分支上 zram 补丁 &quot;zram: avoid duplicate slots in batched writeback&quot; 的构建成功结果，在 242 个配置上完成测试，覆盖 alpha、arc 等多种架构和 gcc/clang 编译器组合。</p><blockquote><p><strong>学习价值</strong>：展示了 0-Day/LKP 自动化测试体系如何对 mm 子系统补丁做跨架构编译验证，是了解内核 CI 流程的实例。</p></blockquote><h3 id="f915d898c779-·-patch-v3-4-4-mm-damon-core-use-node-counters-instead-of-flushing-the-root-memcg-1" tabindex="-1"><code>f915d898c779</code> · <a href="https://lore.kernel.org/all/20261114002822.1043378-5-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 4/4] mm/damon/core: use node counters instead of flushing the root memcg</a> <a class="header-anchor" href="#f915d898c779-·-patch-v3-4-4-mm-damon-core-use-node-counters-instead-of-flushing-the-root-memcg-1" aria-label="Permalink to &quot;`f915d898c779` · [[PATCH v3 4/4] mm/damon/core: use node counters instead of flushing the root memcg](https://lore.kernel.org/all/20261114002822.1043378-5-joannelkoong@gmail.com/)&quot;">​</a></h3><p><em>Joanne Koong (<a href="mailto:joannelkoong@gmail.com" target="_blank" rel="noreferrer">joannelkoong@gmail.com</a>)｜linux-mm</em></p><p>该补丁修改 damos_get_node_memcg_used_bp()，在评估 DAMON goal 时对 root memcg 跳过 memcg stats flush。此前对 root memcg 的 flush 会级联刷新系统中所有 cgroup 且没有限流，开销很大；现在 lruvec_page_state() 可直接从始终最新的 node counters 读取 root memcg 的 LRU 大小。</p><blockquote><p><strong>学习价值</strong>：揭示了 memcg rstat flush 的全局代价以及 node counters 优化路径，对理解 DAMON 与 memcg 统计机制很有价值。</p></blockquote><h3 id="f624b3129316-·-patch-v3-3-4-mm-workingset-skip-the-root-memcg-flush-in-workingset-test-recent" tabindex="-1"><code>f624b3129316</code> · <a href="https://lore.kernel.org/all/20261114002822.1043378-4-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 3/4] mm: workingset: skip the root memcg flush in workingset_test_recent()</a> <a class="header-anchor" href="#f624b3129316-·-patch-v3-3-4-mm-workingset-skip-the-root-memcg-flush-in-workingset-test-recent" aria-label="Permalink to &quot;`f624b3129316` · [[PATCH v3 3/4] mm: workingset: skip the root memcg flush in workingset_test_recent()](https://lore.kernel.org/all/20261114002822.1043378-4-joannelkoong@gmail.com/)&quot;">​</a></h3><p><em>Joanne Koong (<a href="mailto:joannelkoong@gmail.com" target="_blank" rel="noreferrer">joannelkoong@gmail.com</a>)｜linux-mm</em></p><p>该补丁在 workingset_test_recent() 中当 eviction memcg 为 root memcg 时跳过 rstat flush，避免 refault 路径上昂贵的全系统 cgroup 刷新。但 reclaim 路径仍需保留 flush，因为全局回收会读取子 memcg 的 rstat 统计。</p><blockquote><p><strong>学习价值</strong>：结合 workingset/refault 机制讲解 rstat flush 的取舍，是学习内存回收与统计一致性的好案例。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="edddffcbf97f-·-patch-net-net-stmmac-re-enable-on-chip-parity-checkers-for-xgmac-asp-0x2" tabindex="-1"><code>edddffcbf97f</code> · <a href="https://lore.kernel.org/all/20261114015554.2187341-1-zxyan0222@gmail.com/" target="_blank" rel="noreferrer">[PATCH net] net: stmmac: re-enable on-chip parity checkers for XGMAC ASP 0x2</a> <a class="header-anchor" href="#edddffcbf97f-·-patch-net-net-stmmac-re-enable-on-chip-parity-checkers-for-xgmac-asp-0x2" aria-label="Permalink to &quot;`edddffcbf97f` · [[PATCH net] net: stmmac: re-enable on-chip parity checkers for XGMAC ASP 0x2](https://lore.kernel.org/all/20261114015554.2187341-1-zxyan0222@gmail.com/)&quot;">​</a></h3><p><em>Zxyan Zhu (<a href="mailto:zxyan0222@gmail.com" target="_blank" rel="noreferrer">zxyan0222@gmail.com</a>)｜netdev</em></p><p>该补丁修正了 stmmac 驱动中对 XGMAC MAC_HW_Feature3 寄存器 ASP 字段的误解：之前的提交误以为 ASP 0x2 (AS_NEPPE) 没有奇偶校验保护而提前退出，但根据 DWC_xgmac databook，0x2 仍包含片上安全特性，只是外部应用接口没有 ECC/parity 端口，因此重新启用片上 parity checkers。</p><blockquote><p><strong>学习价值</strong>：体现了驱动开发中仔细阅读硬件手册、纠正寄存器位段语义解读的重要性。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="_5e4f7834d14d-·-announcing-xraid-declustered-parity-raid-for-zoned-xfs-1" tabindex="-1"><code>5e4f7834d14d</code> · <a href="https://lwn.net/Articles/1107473/" target="_blank" rel="noreferrer">Announcing XRAID: declustered parity RAID for zoned XFS</a> <a class="header-anchor" href="#_5e4f7834d14d-·-announcing-xraid-declustered-parity-raid-for-zoned-xfs-1" aria-label="Permalink to &quot;`5e4f7834d14d` · [Announcing XRAID: declustered parity RAID for zoned XFS](https://lwn.net/Articles/1107473/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Christoph Hellwig 发布了 XRAID 的首个公开版本，这是集成到 XFS 中的 declustered parity RAID 实现。其两大目标是支持 SMR 等分区设备（zoned devices）上的 parity RAID，以及提供没有固有数据一致性问题的快速 RAID 实现；在传统硬盘上写入速度最高比 mdraid 快 20 倍。该项目已开发一年半，距离合并到主线仍需时间。</p><blockquote><p><strong>学习价值</strong>：对学习文件系统与存储栈（XFS、zoned devices、RAID）的读者极具价值，展示了文件系统级 RAID 设计的前沿方向。</p></blockquote><h3 id="b242cce2919a-·-xraid-publicly-released-as-new-raid-implementation-for-xfs" tabindex="-1"><code>b242cce2919a</code> · <a href="https://www.phoronix.com/news/XRAID-XFS-RAID" target="_blank" rel="noreferrer">XRAID Publicly Released As New RAID Implementation For XFS</a> <a class="header-anchor" href="#b242cce2919a-·-xraid-publicly-released-as-new-raid-implementation-for-xfs" aria-label="Permalink to &quot;`b242cce2919a` · [XRAID Publicly Released As New RAID Implementation For XFS](https://www.phoronix.com/news/XRAID-XFS-RAID)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Christoph Hellwig 发布了 XRAID 的首个公开版本，这是一套集成到 XFS 文件系统内部的 declustered parity RAID 实现，主要面向 zoned XFS 部署场景。与传统的 mdraid 层级式方案不同，XRAID 将 RAID 逻辑下沉到文件系统内部以获得更好的数据布局。</p><blockquote><p><strong>学习价值</strong>：展示了文件系统与 RAID 融合的新趋势，有助于理解 declustered RAID 相对传统 mdraid 的设计优势。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="f40dece8d4c0-·-patch-v8-1-3-rust-helpers-add-spi-helpers" tabindex="-1"><code>f40dece8d4c0</code> · <a href="https://lore.kernel.org/all/tencent_848DC4EA263ADC71A4F3580EE4AB9A687009@qq.com/" target="_blank" rel="noreferrer">[PATCH v8 1/3] rust: helpers: add SPI helpers</a> <a class="header-anchor" href="#f40dece8d4c0-·-patch-v8-1-3-rust-helpers-add-spi-helpers" aria-label="Permalink to &quot;`f40dece8d4c0` · [[PATCH v8 1/3] rust: helpers: add SPI helpers](https://lore.kernel.org/all/tencent_848DC4EA263ADC71A4F3580EE4AB9A687009@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>为 C 中 static inline 的 SPI 函数（spi_unregister_driver()、spi_write()、spi_read()）添加 Rust 可调用的 C helper，并用 CONFIG_SPI 保护。同时在 bindgen 的 bindings_helper.h 中引入 &lt;linux/spi/spi.h&gt;，使 Rust 侧能访问 SPI 数据类型。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 绑定如何通过 helpers 层桥接 C 的 static inline 函数，是理解 Rust/C 互操作机制的典型范例。</p></blockquote><h3 id="b71efb144052-·-patch-v8-2-3-rust-spi-add-spi-driver-abstractions" tabindex="-1"><code>b71efb144052</code> · <a href="https://lore.kernel.org/all/tencent_9EE5F19BC870FDC4DC279ADD67A4B358AC09@qq.com/" target="_blank" rel="noreferrer">[PATCH v8 2/3] rust: spi: add SPI driver abstractions</a> <a class="header-anchor" href="#b71efb144052-·-patch-v8-2-3-rust-spi-add-spi-driver-abstractions" aria-label="Permalink to &quot;`b71efb144052` · [[PATCH v8 2/3] rust: spi: add SPI driver abstractions](https://lore.kernel.org/all/tencent_9EE5F19BC870FDC4DC279ADD67A4B358AC09@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>为 SPI 子系统添加 Rust 抽象层，包括 spi::DeviceId、spi::Adapter（驱动注册）、spi::Driver trait（probe/shutdown/unbind 回调）、spi::SpiDevice（设备配置访问与 I/O）以及 spi::Transfer 等，使 SPI 驱动可以用 Rust 编写。</p><blockquote><p><strong>学习价值</strong>：是学习如何用 Rust trait 和安全抽象封装 C 驱动框架的完整参考实现。</p></blockquote><h3 id="cf1c86888519-·-patch-v8-3-3-samples-rust-add-spi-driver-sample" tabindex="-1"><code>cf1c86888519</code> · <a href="https://lore.kernel.org/all/tencent_680CDC69A5435998E4719B6A703BC5642609@qq.com/" target="_blank" rel="noreferrer">[PATCH v8 3/3] samples: rust: add SPI driver sample</a> <a class="header-anchor" href="#cf1c86888519-·-patch-v8-3-3-samples-rust-add-spi-driver-sample" aria-label="Permalink to &quot;`cf1c86888519` · [[PATCH v8 3/3] samples: rust: add SPI driver sample](https://lore.kernel.org/all/tencent_680CDC69A5435998E4719B6A703BC5642609@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>新增 samples/rust/rust_driver_spi.rs 示例驱动，演示前两个补丁引入的 Rust SPI 抽象的用法，并配套添加 Kconfig 选项 SAMPLE_RUST_DRIVER_SPI 和 Makefile 条目。</p><blockquote><p><strong>学习价值</strong>：简短的示例代码是上手编写 Rust 内核驱动的最佳入门材料。</p></blockquote><h3 id="c8ee564f3909-·-patch-v8-0-3-rust-spi-add-spi-driver-abstractions-1" tabindex="-1"><code>c8ee564f3909</code> · <a href="https://lore.kernel.org/all/tencent_5FBF490F375F4C66A2C8DD421A8E8542FE05@qq.com/" target="_blank" rel="noreferrer">[PATCH v8 0/3] rust: spi: add SPI driver abstractions</a> <a class="header-anchor" href="#c8ee564f3909-·-patch-v8-0-3-rust-spi-add-spi-driver-abstractions-1" aria-label="Permalink to &quot;`c8ee564f3909` · [[PATCH v8 0/3] rust: spi: add SPI driver abstractions](https://lore.kernel.org/all/tencent_5FBF490F375F4C66A2C8DD421A8E8542FE05@qq.com/)&quot;">​</a></h3><p><em>Shuai Liu (<a href="mailto:847807867@qq.com" target="_blank" rel="noreferrer">847807867@qq.com</a>)｜rust-for-linux</em></p><p>本系列 cover letter 汇总了为 SPI 子系统添加 Rust 抽象的三部分补丁（helpers、抽象层、示例驱动）。v8 相对 v7 的主要变化是 rebase 到 linux-next、改为全新邮件线程发送，并根据 Mark Brown 的评审意见将设备 I/O 重构为映射到 spi_sync() 的 transfer() 原语。</p><blockquote><p><strong>学习价值</strong>：通过版本演进记录展示了内核社区评审驱动的迭代过程，可学习补丁系列的组织与回应评审的方式。</p></blockquote><h3 id="_58c805cf8f6a-·-patch-objtool-rust-add-more-noreturn-rust-functions-for-rust-1-101-0" tabindex="-1"><code>58c805cf8f6a</code> · <a href="https://lore.kernel.org/all/20261114001708.80599-1-ojeda@kernel.org/" target="_blank" rel="noreferrer">[PATCH] objtool/rust: add more <code>noreturn</code> Rust functions for Rust 1.101.0</a> <a class="header-anchor" href="#_58c805cf8f6a-·-patch-objtool-rust-add-more-noreturn-rust-functions-for-rust-1-101-0" aria-label="Permalink to &quot;`58c805cf8f6a` · [[PATCH] objtool/rust: add more `noreturn` Rust functions for Rust 1.101.0](https://lore.kernel.org/all/20261114001708.80599-1-ojeda@kernel.org/)&quot;">​</a></h3><p><em>Miguel Ojeda (<a href="mailto:ojeda@kernel.org" target="_blank" rel="noreferrer">ojeda@kernel.org</a>)｜rust-for-linux</em></p><p>Rust 1.101.0 起，<code>unreachable!()</code> 等无参数 panic 宏会调用新外联的 <code>core::panicking::unreachable_default_msg</code> 符号，导致 objtool 报出函数 &quot;falls through to next function&quot; 警告。该补丁在 objtool 的 noreturn 函数列表中补充这些新的 Rust panic 符号。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 编译器行为变化如何影响内核 objtool 验证，是理解 Rust 与内核构建工具链交互的好案例。</p></blockquote><h3 id="c0a721c2ccd1-·-patch-1-1-rust-pwm-reject-over-aligned-driver-data-in-chip-new" tabindex="-1"><code>c0a721c2ccd1</code> · <a href="https://lore.kernel.org/all/caddec5478a0d39a73152247a60bc21b3c609cc7.1794600927.git.pgovind2@uci.edu/" target="_blank" rel="noreferrer">[PATCH 1/1] rust: pwm: reject over-aligned driver data in <code>Chip::new()</code></a> <a class="header-anchor" href="#c0a721c2ccd1-·-patch-1-1-rust-pwm-reject-over-aligned-driver-data-in-chip-new" aria-label="Permalink to &quot;`c0a721c2ccd1` · [[PATCH 1/1] rust: pwm: reject over-aligned driver data in `Chip::new()`](https://lore.kernel.org/all/caddec5478a0d39a73152247a60bc21b3c609cc7.1794600927.git.pgovind2@uci.edu/)&quot;">​</a></h3><p><em>Priya Bala Govindasamy (<a href="mailto:pgovind2@uci.edu" target="_blank" rel="noreferrer">pgovind2@uci.edu</a>)｜rust-for-linux</em></p><p><code>Chip::new()</code> 未检查驱动私有数据类型 <code>T</code> 的对齐要求，而 <code>pwmchip_alloc()</code> 分配的存储仅按 <code>PWMCHIP_ALIGN</code>（即 <code>ARCH_DMA_MINALIGN</code>）对齐。若 <code>T</code> 要求更高对齐，<code>drvdata_ptr</code> 可能指向未对齐存储，导致未定义行为。补丁在 <code>Chip::new()</code> 中拒绝过度对齐的驱动数据。</p><blockquote><p><strong>学习价值</strong>：典型的 Rust 抽象层与 C 分配器对齐语义不匹配的 soundness 问题，对学习内核 Rust 安全边界很有价值。</p></blockquote><h3 id="e40de6443c70-·-patch-0-1-rust-pwm-reject-over-aligned-driver-data-in-chip-new-1" tabindex="-1"><code>e40de6443c70</code> · <a href="https://lore.kernel.org/all/cover.1794600927.git.pgovind2@uci.edu/" target="_blank" rel="noreferrer">[PATCH 0/1] rust: pwm: reject over-aligned driver data in <code>Chip::new()</code></a> <a class="header-anchor" href="#e40de6443c70-·-patch-0-1-rust-pwm-reject-over-aligned-driver-data-in-chip-new-1" aria-label="Permalink to &quot;`e40de6443c70` · [[PATCH 0/1] rust: pwm: reject over-aligned driver data in `Chip::new()`](https://lore.kernel.org/all/cover.1794600927.git.pgovind2@uci.edu/)&quot;">​</a></h3><p><em>Priya Bala Govindasamy (<a href="mailto:pgovind2@uci.edu" target="_blank" rel="noreferrer">pgovind2@uci.edu</a>)｜rust-for-linux</em></p><p>该补丁系列由 FerroLens 工具（内部使用 LLM 检测 Rust 内核代码潜在 unsound 行为并经人工验证）发现的问题驱动。问题为 rust/kernel/pwm.rs 中 <code>Chip::new()</code> 未检查驱动数据类型 <code>T</code> 的对齐，可能导致 <code>pwmchip_alloc()</code> 分配的存储不满足 <code>T</code> 的对齐要求。</p><blockquote><p><strong>学习价值</strong>：展示了 LLM 辅助工具在内核 Rust 代码审计中的实际应用，是工具与内核开发结合的有趣范例。</p></blockquote><h3 id="d61d7a7ec7f3-·-patch-v3-3-3-rust-bitmap-kunit-uncomment-owned-bitmap-out-of-bounds-panic-case" tabindex="-1"><code>d61d7a7ec7f3</code> · <a href="https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-3-0d7832c07166@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 3/3] rust: bitmap: kunit: uncomment owned_bitmap_out_of_bounds panic case</a> <a class="header-anchor" href="#d61d7a7ec7f3-·-patch-v3-3-3-rust-bitmap-kunit-uncomment-owned-bitmap-out-of-bounds-panic-case" aria-label="Permalink to &quot;`d61d7a7ec7f3` · [[PATCH v3 3/3] rust: bitmap: kunit: uncomment owned_bitmap_out_of_bounds panic case](https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-3-0d7832c07166@gmail.com/)&quot;">​</a></h3><p><em>Nicolás Antinori via B4 Relay (<a href="mailto:devnull+nico.antinori.7.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+nico.antinori.7.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>Rust KUnit 测试现已支持 <code>#[should_panic]</code> 属性，因此取消注释 bitmap 模块中原本被注释掉的 owned_bitmap_out_of_bounds panic 测试用例，使其在 CONFIG_RUST_BITMAP_HARDENED=y 时可运行。同时调整 <code>#[test]</code> 属性位置以与其他测试保持一致。</p><blockquote><p><strong>学习价值</strong>：说明新测试特性如何解锁之前无法编写的边界条件测试，体现测试基础设施演进的连锁效应。</p></blockquote><h3 id="_28617686940d-·-patch-v3-0-3-rust-kunit-support-should-panic-and-same-test-name-with-different-cfg" tabindex="-1"><code>28617686940d</code> · <a href="https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-0-0d7832c07166@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 0/3] rust: kunit: support #[should_panic] and same test name with different #[cfg(...)]</a> <a class="header-anchor" href="#_28617686940d-·-patch-v3-0-3-rust-kunit-support-should-panic-and-same-test-name-with-different-cfg" aria-label="Permalink to &quot;`28617686940d` · [[PATCH v3 0/3] rust: kunit: support #[should_panic] and same test name with different #[cfg(...)]](https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-0-0d7832c07166@gmail.com/)&quot;">​</a></h3><p><em>Nicolás Antinori via B4 Relay (<a href="mailto:devnull+nico.antinori.7.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+nico.antinori.7.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>该系列补丁为 Rust 编写的 KUnit 测试实现两项功能：<code>#[should_panic]</code> 属性支持和允许同名测试在不同 <code>#[cfg(...)]</code> 配置下共存。v3 回归到基于 <code>#[panic_handler]</code> 的实现，仅捕获 Rust panic，并在 <code>kunit</code> 结构体中添加 <code>kunit_attributes</code> 指针以读取测试属性。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust panic 机制如何与 KUnit 框架集成，是理解内核测试基础设施与 Rust 交互的绝佳材料。</p></blockquote><h3 id="_77ab7a8d29e3-·-patch-v3-1-3-rust-kunit-add-should-panic-support" tabindex="-1"><code>77ab7a8d29e3</code> · <a href="https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-1-0d7832c07166@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 1/3] rust: kunit: add #[should_panic] support</a> <a class="header-anchor" href="#_77ab7a8d29e3-·-patch-v3-1-3-rust-kunit-add-should-panic-support" aria-label="Permalink to &quot;`77ab7a8d29e3` · [[PATCH v3 1/3] rust: kunit: add #[should_panic] support](https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-1-0d7832c07166@gmail.com/)&quot;">​</a></h3><p><em>Nicolás Antinori via B4 Relay (<a href="mailto:devnull+nico.antinori.7.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+nico.antinori.7.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>为 Rust KUnit 测试添加 <code>#[should_panic]</code> 属性支持，允许测试预期会触发 panic 的条件并将其报告为成功。实现涉及 <code>rust/kernel/lib.rs</code> 中的 <code>#[panic_handler]</code>、<code>include/kunit/test.h</code> 以及 kunit 核心代码的修改。</p><blockquote><p><strong>学习价值</strong>：详细展示了跨语言（Rust/C）测试框架扩展的实现细节，对学习内核测试基础设施很有参考价值。</p></blockquote><h3 id="a91a34ad0ddc-·-patch-v3-2-3-rust-kunit-allow-same-test-name-with-different-cfg" tabindex="-1"><code>a91a34ad0ddc</code> · <a href="https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-2-0d7832c07166@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 2/3] rust: kunit: allow same test name with different #[cfg(...)]</a> <a class="header-anchor" href="#a91a34ad0ddc-·-patch-v3-2-3-rust-kunit-allow-same-test-name-with-different-cfg" aria-label="Permalink to &quot;`a91a34ad0ddc` · [[PATCH v3 2/3] rust: kunit: allow same test name with different #[cfg(...)]](https://lore.kernel.org/all/20261113-rust_kunit_v6_send-v3-2-0d7832c07166@gmail.com/)&quot;">​</a></h3><p><em>Nicolás Antinori via B4 Relay (<a href="mailto:devnull+nico.antinori.7.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+nico.antinori.7.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>当前在 Rust KUnit 测试中，不同 <code>#[cfg(...)</code> 属性下定义同名测试会导致编译错误。该补丁移除这一限制，允许在不同配置下定义同名测试，以便在不同配置下测试相同的代码路径。</p><blockquote><p><strong>学习价值</strong>：一个简洁的宏改进案例，说明 Rust 内核测试语法如何逐步向用户空间测试习惯靠拢。</p></blockquote><h3 id="_1b9b096ba1b2-·-patch-v8-3-3-drm-tyr-put-iomem-behind-the-hardware-gate" tabindex="-1"><code>1b9b096ba1b2</code> · <a href="https://lore.kernel.org/all/20261113-tyr-reset-impl-v8-3-2ee298ac9808@onurozkan.dev/" target="_blank" rel="noreferrer">[PATCH v8 3/3] drm/tyr: put iomem behind the hardware gate</a> <a class="header-anchor" href="#_1b9b096ba1b2-·-patch-v8-3-3-drm-tyr-put-iomem-behind-the-hardware-gate" aria-label="Permalink to &quot;`1b9b096ba1b2` · [[PATCH v8 3/3] drm/tyr: put iomem behind the hardware gate](https://lore.kernel.org/all/20261113-tyr-reset-impl-v8-3-2ee298ac9808@onurozkan.dev/)&quot;">​</a></h3><p><em>Onur Özkan (work@onurozkan.dev)｜rust-for-linux</em></p><p>将 drm/tyr 驱动的 iomem 映射移入 HwGate 之后，通过传递 <code>Arc&lt;HwGate&gt;</code> 给访问硬件的组件，调用者需先获取 <code>HwAccessGuard</code> 才能访问 iomem，使 reset worker 能等待进行中的访问。每次 address-space 操作只获取一次 gate 并传递受保护的 iomem 引用，避免嵌套获取导致与 reset 死锁。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust RAII guard 模式在 GPU 驱动并发控制中的实际应用，是学习内核 Rust 同步设计的优秀范例。</p></blockquote><h3 id="_5d01f5a38f27-·-patch-v3-fault-inject-rust-add-a-rust-api-for-fault-injection" tabindex="-1"><code>5d01f5a38f27</code> · <a href="https://lore.kernel.org/all/20261113-rust-fault-inject-v3-1-d8bd240f22dc@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3] fault-inject: rust: add a Rust API for fault-injection</a> <a class="header-anchor" href="#_5d01f5a38f27-·-patch-v3-fault-inject-rust-add-a-rust-api-for-fault-injection" aria-label="Permalink to &quot;`5d01f5a38f27` · [[PATCH v3] fault-inject: rust: add a Rust API for fault-injection](https://lore.kernel.org/all/20261113-rust-fault-inject-v3-1-d8bd240f22dc@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>为 Rust 代码添加 fault-injection API，允许创建故障注入控制点，这些控制点可作为默认组挂载到 configfs 树并由用户空间控制。内核侧提供 <code>should_fail</code> 方法查询某操作是否应失败。该补丁是 Rust null block 驱动故障注入特性的依赖。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 Rust 封装现有的 C fault-injection 基础设施，是学习跨语言 API 设计的好例子。</p></blockquote><h3 id="_1fb4eec72d0b-·-patch-v8-2-3-drm-tyr-add-gpu-reset-infrastructure" tabindex="-1"><code>1fb4eec72d0b</code> · <a href="https://lore.kernel.org/all/20261113-tyr-reset-impl-v8-2-2ee298ac9808@onurozkan.dev/" target="_blank" rel="noreferrer">[PATCH v8 2/3] drm/tyr: add GPU reset infrastructure</a> <a class="header-anchor" href="#_1fb4eec72d0b-·-patch-v8-2-3-drm-tyr-add-gpu-reset-infrastructure" aria-label="Permalink to &quot;`1fb4eec72d0b` · [[PATCH v8 2/3] drm/tyr: add GPU reset infrastructure](https://lore.kernel.org/all/20261113-tyr-reset-impl-v8-2-2ee298ac9808@onurozkan.dev/)&quot;">​</a></h3><p><em>Onur Özkan (work@onurozkan.dev)｜rust-for-linux</em></p><p>为 drm/tyr 驱动添加 GPU reset 基础设施：在专用 workqueue 上调度 reset，跟踪 reset 状态避免重复排队，使用基于 SRCU 的 gate 配合 mutex 保护的读者准入来阻塞 reset 期间的硬件访问。teardown 时停止新的 reset 请求并排空队列中或运行中的 reset 工作后再释放设备资源。</p><blockquote><p><strong>学习价值</strong>：深入展示 SRCU、workqueue 与互斥机制在 GPU reset 场景的组合运用，对学习内核并发控制极具价值。</p></blockquote><h3 id="cf781eb68afd-·-patch-v8-1-3-drm-tyr-clear-stale-irq-state-before-soft-reset" tabindex="-1"><code>cf781eb68afd</code> · <a href="https://lore.kernel.org/all/20261113-tyr-reset-impl-v8-1-2ee298ac9808@onurozkan.dev/" target="_blank" rel="noreferrer">[PATCH v8 1/3] drm/tyr: clear stale IRQ state before soft reset</a> <a class="header-anchor" href="#cf781eb68afd-·-patch-v8-1-3-drm-tyr-clear-stale-irq-state-before-soft-reset" aria-label="Permalink to &quot;`cf781eb68afd` · [[PATCH v8 1/3] drm/tyr: clear stale IRQ state before soft reset](https://lore.kernel.org/all/20261113-tyr-reset-impl-v8-1-2ee298ac9808@onurozkan.dev/)&quot;">​</a></h3><p><em>Onur Özkan (work@onurozkan.dev)｜rust-for-linux</em></p><p>该补丁修复了 Rust 编写的 drm/tyr GPU 驱动中 soft reset 的竞态问题：上一次 reset 可能遗留已置位的 reset completed IRQ，导致 poll 过早返回。补丁在发起 soft reset 前先清除 stale IRQ 状态，确保驱动等待的是当前这次 reset 真正完成。改动仅 3 行，位于 driver.rs。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust GPU 驱动开发中硬件状态清理的经典模式，对学习 Rust in Linux 驱动编写和 IRQ/poll 时序问题很有参考价值。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="a21d20d1fdea-·-next-20261113-linux-next" tabindex="-1"><code>a21d20d1fdea</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261113-2026-11-13" target="_blank" rel="noreferrer">next-20261113: linux-next</a> <a class="header-anchor" href="#a21d20d1fdea-·-next-20261113-linux-next" aria-label="Permalink to &quot;`a21d20d1fdea` · [next-20261113: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261113-2026-11-13)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 13 日发布 next-20261113 版本。linux-next 是各子系统树合并后的集成测试树，供下一个合并窗口前的整体测试使用。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 版本发布有助于学习者了解内核开发节奏和即将进入主线的变化。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_558b96cf51e4-·-25-years-of-buildroot" tabindex="-1"><code>558b96cf51e4</code> · <a href="https://lwn.net/Articles/1103395/" target="_blank" rel="noreferrer">[$] 25 years of Buildroot</a> <a class="header-anchor" href="#_558b96cf51e4-·-25-years-of-buildroot" aria-label="Permalink to &quot;`558b96cf51e4` · [[$] 25 years of Buildroot](https://lwn.net/Articles/1103395/)&quot;">​</a></h3><p><em>jake｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Buildroot 维护者 Peter Korsgaard 在 2026 年 Embedded Linux Conference Europe 上回顾了该嵌入式 Linux 构建工具 25 年的发展历程，并介绍了项目现状与未来规划。Buildroot 长期以来是嵌入式 Linux 世界的基石之一。</p><blockquote><p><strong>学习价值</strong>：帮助学习者理解嵌入式 Linux 构建生态的历史脉络，但与内核源码本身关联较弱。</p></blockquote><h3 id="_6ce23f2a9739-·-security-updates-for-friday" tabindex="-1"><code>6ce23f2a9739</code> · <a href="https://lwn.net/Articles/1107472/" target="_blank" rel="noreferrer">Security updates for Friday</a> <a class="header-anchor" href="#_6ce23f2a9739-·-security-updates-for-friday" aria-label="Permalink to &quot;`6ce23f2a9739` · [Security updates for Friday](https://lwn.net/Articles/1107472/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux、Debian、Fedora 等发行版发布了一批安全更新，涉及 kernel、kernel-rt、linux-6.12、nginx、postgresql 等众多软件包。这是 LWN 的例行安全更新汇总。</p><blockquote><p><strong>学习价值</strong>：可帮助学习者跟踪各发行版内核安全补丁的发布节奏，但内容本身为列表式信息。</p></blockquote><h3 id="d3ce0870d476-·-wine-11-22-introduces-x86-avx-emulation-on-arm64" tabindex="-1"><code>d3ce0870d476</code> · <a href="https://www.phoronix.com/news/Wine-11.22-Released" target="_blank" rel="noreferrer">Wine 11.22 Introduces x86 AVX Emulation On ARM64</a> <a class="header-anchor" href="#d3ce0870d476-·-wine-11-22-introduces-x86-avx-emulation-on-arm64" aria-label="Permalink to &quot;`d3ce0870d476` · [Wine 11.22 Introduces x86 AVX Emulation On ARM64](https://www.phoronix.com/news/Wine-11.22-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Wine 11.22 作为双周开发版发布，新增了在 ARM64 上模拟 x86 AVX 指令集的能力，并逐步接近 Wine 12.0 稳定版的准备阶段。</p><blockquote><p><strong>学习价值</strong>：属于用户态 Windows 兼容层新闻，与内核学习关系不大，仅供了解跨架构二进制兼容的生态动态。</p></blockquote><h3 id="c2d4386f3f07-·-cloudflare-open-sources-kitesurf-their-web-browser-for-ai-agents" tabindex="-1"><code>c2d4386f3f07</code> · <a href="https://www.phoronix.com/news/Cloudflare-Kitesurf-Open-Source" target="_blank" rel="noreferrer">Cloudflare Open Sources Kitesurf: Their Web Browser For AI Agents</a> <a class="header-anchor" href="#c2d4386f3f07-·-cloudflare-open-sources-kitesurf-their-web-browser-for-ai-agents" aria-label="Permalink to &quot;`c2d4386f3f07` · [Cloudflare Open Sources Kitesurf: Their Web Browser For AI Agents](https://www.phoronix.com/news/Cloudflare-Kitesurf-Open-Source)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Cloudflare 宣布开源 Kitesurf，这是一个面向 AI agent 的无状态（stateless）网页浏览器，此前已开发完善了其功能特性。</p><blockquote><p><strong>学习价值</strong>：属于 AI 应用层开源项目，与 Linux 内核学习基本无关。</p></blockquote><h3 id="b9399796362e-·-amd-opensil-achieves-its-production-goal-with-6th-gen-epyc-venice" tabindex="-1"><code>b9399796362e</code> · <a href="https://www.phoronix.com/news/AMD-openSIL-Venice-Goal" target="_blank" rel="noreferrer">AMD openSIL Achieves Its Production Goal With 6th Gen EPYC &quot;Venice&quot;</a> <a class="header-anchor" href="#b9399796362e-·-amd-opensil-achieves-its-production-goal-with-6th-gen-epyc-venice" aria-label="Permalink to &quot;`b9399796362e` · [AMD openSIL Achieves Its Production Goal With 6th Gen EPYC &quot;Venice&quot;](https://www.phoronix.com/news/AMD-openSIL-Venice-Goal)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 的 openSIL 项目旨在以开源的 CPU 硅初始化代码取代传统 AGESA，其生产就绪目标原定于 Zen 6。随着本周 EPYC 9006 SP7（Venice）的发布，openSIL 据称已达成生产目标，此前 Zen 5 上已有配合 Coreboot 的概念验证。</p><blockquote><p><strong>学习价值</strong>：对理解固件初始化链（openSIL/Coreboot/AGESA）与 Linux 引导早期阶段有帮助，适合关注固件与内核衔接的学习者。</p></blockquote><h3 id="bbb5955d7069-·-kde-frameworks-6-32-released-with-that-fix-for-usb-file-transfer-notifications" tabindex="-1"><code>bbb5955d7069</code> · <a href="https://www.phoronix.com/news/KDE-Frameworks-6.32" target="_blank" rel="noreferrer">KDE Frameworks 6.32 Released With That Fix For USB File Transfer Notifications</a> <a class="header-anchor" href="#bbb5955d7069-·-kde-frameworks-6-32-released-with-that-fix-for-usb-file-transfer-notifications" aria-label="Permalink to &quot;`bbb5955d7069` · [KDE Frameworks 6.32 Released With That Fix For USB File Transfer Notifications](https://www.phoronix.com/news/KDE-Frameworks-6.32)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KDE Frameworks 6.32 发布，本次月度更新的亮点是修复了一个存在 15 年之久的 USB 文件传输通知进度不准确的 bug。</p><blockquote><p><strong>学习价值</strong>：属于桌面用户态组件更新，对内核学习价值有限。</p></blockquote><h3 id="_71efb1908617-·-linux-7-5-to-include-new-hwpoison-panic-tool-for-intentionally-crashing-your-system-1" tabindex="-1"><code>71efb1908617</code> · <a href="https://www.phoronix.com/news/Linux-7.5-hwpoison-panic" target="_blank" rel="noreferrer">Linux 7.5 To Include New hwpoison-panic Tool For Intentionally Crashing Your System</a> <a class="header-anchor" href="#_71efb1908617-·-linux-7-5-to-include-new-hwpoison-panic-tool-for-intentionally-crashing-your-system-1" aria-label="Permalink to &quot;`71efb1908617` · [Linux 7.5 To Include New hwpoison-panic Tool For Intentionally Crashing Your System](https://www.phoronix.com/news/Linux-7.5-hwpoison-panic)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>预计合并进 Linux 7.5 的新工具 hwpoison-panic 可通过 hwpoison 机制故意注入内存错误使系统崩溃，用于测试和演练内核的硬件错误处理路径。这是 RAS（可靠性、可用性、可服务性）测试基础设施的一部分。</p><blockquote><p><strong>学习价值</strong>：对学习内存管理中的 hwpoison 机制和 RAS 错误处理路径很有参考价值，展示了内核如何做故障注入测试。</p></blockquote><h3 id="_2d4706943b10-·-amd-aocl-6-0-introduces-new-rng-library-initial-zen-6-cpu-optimizations" tabindex="-1"><code>2d4706943b10</code> · <a href="https://www.phoronix.com/news/AMD-AOCL-6.0" target="_blank" rel="noreferrer">AMD AOCL 6.0 Introduces New RNG Library, Initial Zen 6 CPU Optimizations</a> <a class="header-anchor" href="#_2d4706943b10-·-amd-aocl-6-0-introduces-new-rng-library-initial-zen-6-cpu-optimizations" aria-label="Permalink to &quot;`2d4706943b10` · [AMD AOCL 6.0 Introduces New RNG Library, Initial Zen 6 CPU Optimizations](https://www.phoronix.com/news/AMD-AOCL-6.0)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 发布 AOCL 6.0（AMD Optimizing CPU Libraries），新增随机数生成（RNG）库，并带来对 Zen 6 CPU 的初步优化，与同周发布的 AOCC 6.0 编译器配套。</p><blockquote><p><strong>学习价值</strong>：属于用户态优化库发布，与内核学习关联较弱，仅供了解 AMD 软件生态。</p></blockquote><h3 id="_5302dea82576-·-linux-7-5-to-upstream-driver-for-new-glanda-gpu" tabindex="-1"><code>5302dea82576</code> · <a href="https://www.phoronix.com/news/Linux-7.5-GlandaGPU-Driver" target="_blank" rel="noreferrer">Linux 7.5 To Upstream Driver For New Glanda GPU</a> <a class="header-anchor" href="#_5302dea82576-·-linux-7-5-to-upstream-driver-for-new-glanda-gpu" aria-label="Permalink to &quot;`5302dea82576` · [Linux 7.5 To Upstream Driver For New Glanda GPU](https://www.phoronix.com/news/Linux-7.5-GlandaGPU-Driver)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>drm-misc-next 本周的 pull request 中最引人注目的是新增的 GlandaGPU 驱动，将随 DRM-Next 进入 Linux 7.5 合并窗口（预计 12 月下旬开启）。该 PR 还包含其他 DRM 子系统的新增内容。</p><blockquote><p><strong>学习价值</strong>：可借此了解 DRM 驱动通过 drm-misc 树进入主线的提交流程与合并窗口节奏。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>5e4f7834d14d</code> · <a href="https://lwn.net/Articles/1107473/" target="_blank" rel="noreferrer">Announcing XRAID: declustered parity RAID for zoned XFS</a></li><li><code>c8ee564f3909</code> · <a href="https://lore.kernel.org/all/tencent_5FBF490F375F4C66A2C8DD421A8E8542FE05@qq.com/" target="_blank" rel="noreferrer">[PATCH v8 0/3] rust: spi: add SPI driver abstractions</a></li><li><code>f915d898c779</code> · <a href="https://lore.kernel.org/all/20261114002822.1043378-5-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 4/4] mm/damon/core: use node counters instead of flushing the root memcg</a></li><li><code>e40de6443c70</code> · <a href="https://lore.kernel.org/all/cover.1794600927.git.pgovind2@uci.edu/" target="_blank" rel="noreferrer">[PATCH 0/1] rust: pwm: reject over-aligned driver data in <code>Chip::new()</code></a></li></ul>',163)])])}const m=r(n,[["render",l]]);export{h as __pageData,m as default};
